from produire import produire,paras,steps,table
parts=[
('La {myélopathie cervicale dégénérative} est une atteinte clinique de la moelle liée à une compression dégénérative cervicale. Elle peut altérer mains, marche et contrôle sphinctérien. Une sténose visible sans symptômes n’est pas le même diagnostic.',paras('Le terme myélopathie décrit une souffrance médullaire. La cause peut être dégénérative, mais aussi tumorale, infectieuse, inflammatoire ou traumatique ; l’étiologie doit être établie.', 'Le diagnostic présenté ici associe signes médullaires compatibles et compression cervicale concordante. Une douleur de nuque n’est pas nécessairement le symptôme dominant.')),
('Le {contexte est souvent une évolution progressive chez l’adulte}. Les signes peuvent s’installer discrètement et par paliers. Le retard diagnostique expose à une perte fonctionnelle qui peut devenir durable.',paras('La plainte initiale peut être une difficulté à boutonner, une maladresse des doigts ou un équilibre moins sûr. Ces symptômes ne doivent pas être attribués automatiquement au vieillissement.', 'Une sténose cervicale découverte fortuitement est fréquente dans certaines populations ; la présence d’une image seule ne permet pas de prédire une myélopathie individuelle.')),
('La {compression médullaire perturbe plusieurs voies}. Des remaniements discaux, osseux et ligamentaires réduisent l’espace disponible. Les contraintes mécaniques et la perfusion médullaire participent à la souffrance.',paras('La moelle cervicale contient des voies motrices et sensitives pour les membres supérieurs et inférieurs. La lésion peut donc associer diminution de dextérité, troubles de marche et signes pyramidaux.', 'Une racine comprimée au même niveau peut donner douleur ou diminution d’un réflexe dans le bras, tandis que les réflexes sont vifs en dessous. Un tableau mixte n’exclut pas la myélopathie.')),
('Le {tri évalue la rapidité d’aggravation}. Déficit nouveau important, marche brutalement compromise ou trouble sphinctérien récent imposent une évaluation urgente. Une évolution chronique suspecte nécessite aussi un avis rapide.',paras('Rechercher traumatisme, fièvre, cancer et contexte d’immunosuppression. Une compression aiguë d’une autre cause ne doit pas être étiquetée dégénérative sur une simple radiographie d’arthrose.', 'Éviter mobilisation forcée, traction non encadrée ou manipulation cervicale tant que la situation n’est pas clarifiée.')),
('L’{anamnèse recherche des pertes fonctionnelles concrètes}. Demander changements d’écriture, boutons, couverts, objets lâchés et chutes. Interroger sur symptômes des jambes et troubles sphinctériens.',paras('Préciser ancienneté, vitesse de progression, latéralité, paresthésies et douleurs radiculaires. Une sensation de décharge déclenchée par les mouvements du cou peut orienter vers une atteinte médullaire mais n’en précise pas la cause.', 'Les antécédents et la fragilité médicale influencent le choix thérapeutique. Documenter aussi l’impact sur autonomie, travail et qualité de vie, que les scores neurologiques ne résument pas entièrement.')),
('L’{examen doit dépasser le cou et le bras douloureux}. Évaluer force, sensibilité, réflexes, tonus et dextérité. Examiner la marche et l’équilibre dans des conditions sûres.',paras('Des réflexes vifs, un clonus ou un signe de Babinski soutiennent une atteinte des voies longues. Le signe de Hoffmann peut contribuer au faisceau d’arguments sans constituer seul un diagnostic.', 'Un examen discret au début ne doit pas faire abandonner une histoire fonctionnelle évocatrice. Comparer aux examens précédents et rechercher des diagnostics associés, notamment neuropathie périphérique.')),
('L’{approche syndromique distingue moelle, racine et nerf périphérique}. Une seule racine cervicale n’explique pas des troubles de marche. Une neuropathie des mains peut toutefois coexister avec une myélopathie.',table(['Syndrome','Éléments utiles'],[['Radiculaire.','Douleur et déficit suivant une racine, réflexe parfois diminué.'],['Médullaire.','Dextérité et marche altérées, signes pyramidaux, plusieurs territoires.'],['Neuropathie périphérique.','Distribution d’un nerf ou polyneuropathie ; ne pas conclure sans examen complet.'],['Autre cause centrale.','Atteinte cérébrale, inflammatoire ou autre maladie médullaire à envisager si discordance.']])) ,
('Le {diagnostic exige une concordance clinique et radiologique}. L’IRM recherche compression, étages concernés et modifications du signal médullaire. Le degré de handicap ne se lit pas dans une seule mesure de canal.',paras('Les symptômes, l’examen et l’imagerie doivent être réunis. Une sténose asymptomatique n’impose pas les mêmes décisions qu’une maladie médullaire clinique.', 'Les classifications de gravité aident à suivre la maladie, mais la douleur, la qualité de vie et la fragilité complètent l’évaluation. Une absence de modification franche du signal n’exclut pas toute atteinte clinique.')),
('L’{IRM cervicale est l’examen clé}. Elle étudie moelle, compression et tissus environnants. Les examens supplémentaires sont choisis pour préciser la cause et préparer la décision.',paras('Une radiographie ne suffit pas à exclure une souffrance médullaire. Le scanner complète parfois l’analyse osseuse ou la planification ; une contre-indication à l’IRM nécessite une stratégie spécialisée.', 'L’électrophysiologie peut aider devant un diagnostic différentiel ou une atteinte associée. Elle ne doit pas retarder l’évaluation d’une compression progressive. Les anomalies de signal ont une valeur pronostique, mais ne permettent pas une promesse individuelle de récupération.')),
('L’{algorithme privilégie reconnaissance et orientation}. Toute suspicion clinique demande une imagerie appropriée et un avis rachidien. Le délai dépend de la progression et de la gravité.',steps('Identifier signes médullaires et écarter une cause aiguë traumatique, infectieuse ou tumorale.', 'Organiser IRM et avis spécialisé ; urgence immédiate si aggravation aiguë importante.', 'Évaluer gravité, évolution, autonomie, fragilité et concordance.', 'Discuter décompression ou, dans certains cas légers stables, suivi structuré.', 'Définir les signes d’aggravation et une surveillance clinique réelle.')),
('La {prise en charge suisse est spécialisée}. La chirurgie de décompression est habituellement recommandée pour les formes modérées ou sévères. Une forme légère stable peut faire discuter chirurgie ou surveillance structurée avec rééducation encadrée.',paras('La synthèse AO Spine de 2025 soutient la chirurgie comme option dans les formes légères, sans preuve comparative suffisante pour l’imposer à toutes. Le choix tient compte de la fonction, de la qualité de vie, de la fragilité et des préférences informées.', 'La surveillance n’est pas une absence de prise en charge : elle exige un suivi et une réévaluation rapide si aggravation. Une douleur modérée ne justifie pas d’attendre lorsque la fonction se détériore.', 'L’objectif opératoire est notamment de prévenir la progression et d’améliorer la fonction lorsqu’une récupération est possible. Des déficits peuvent persister ; aucune récupération complète n’est garantie. Une antalgie éventuelle ne traite pas la compression et ne remplace pas cette décision.')),
('Le {suivi porte sur les mains, la marche et l’autonomie}. Comparer régulièrement les capacités concrètes. Prévenir les chutes et adapter les activités à la sécurité.',paras('Toute faiblesse nouvelle, chute répétée, aggravation de marche ou trouble sphinctérien justifie une réévaluation urgente selon la vitesse d’apparition. Les instructions doivent être compréhensibles pour le patient et ses proches.', 'Après intervention, rééducation et contrôles sont individualisés. Les complications ou signes nouveaux ne sont pas automatiquement attribués à une récupération lente.')),
('Le {point clé} est de reconnaître la souffrance médullaire avant une perte fonctionnelle majeure. Une cervicalgie peut être absente ou modérée. Le suivi d’une forme légère doit être organisé et ne tolère pas une aggravation ignorée.',paras('Distinguer trois situations : sténose radiologique seule, myélopathie légère stable et myélopathie évolutive ou importante. Elles n’appellent ni le même délai ni la même décision.'))]
quiz=[('Une sténose à l’IRM suffit-elle à diagnostiquer une myélopathie clinique ?','Non.'),('La douleur cervicale est-elle forcément intense ?','Non.'),('Quel geste quotidien peut révéler une perte de dextérité ?','Boutonner un vêtement ou écrire.'),('Pourquoi examiner la marche ?','Les voies médullaires cervicales concernent aussi les jambes.'),('Un signe de Hoffmann isolé suffit-il ?','Non, il s’intègre au tableau.'),('Une radiculopathie peut-elle coexister ?','Oui.'),('Une radiographie normale exclut-elle une atteinte médullaire ?','Non.'),('Quel examen est central ?','L’IRM cervicale.'),('L’absence de signal anormal franc exclut-elle toute myélopathie ?','Non, interpréter clinique et imagerie ensemble.'),('Quelle stratégie est habituellement proposée pour une forme modérée ou sévère ?','Une décompression chirurgicale après évaluation spécialisée.'),('Toute forme légère impose-t-elle la même décision ?','Non, discuter chirurgie ou suivi structuré dans les cas stables.'),('Une aggravation permet-elle de poursuivre sans changement la surveillance ?','Non.'),('L’opération garantit-elle une récupération complète ?','Non.'),('Que faire devant faiblesse aiguë et marche compromise ?','Évaluation urgente, sans attente de physiothérapie de routine.')]
produire(3,parts,quiz,(1,3,7,10))
